def minimum_side_jumps(obstacles):
 costs=[1,0,1]
 for obstacle in obstacles[1:]:
  if obstacle:costs[obstacle-1]=10**9
  best=min(costs)+1
  for lane in range(3):
   if obstacle!=lane+1:costs[lane]=min(costs[lane],best)
 return min(costs)

